package main
import("encoding/json";"math";"os";"testing";"path/filepath")
func TestCommonTimelineIndependentNativePhase(t *testing.T){
 rows:=[]map[string]interface{}{};maximum,max_return:=0.,0.;runs:=[]zero_run{{2000,2064},{4000,4064},{6000,6064},{8000,8064}}
 for _,reverse:=range []bool{false,true}{for _,global:=range []float64{0,.37,2.4}{for _,age:=range []float64{-.5,.5}{for _,amplitude:=range []float64{2048,8170}{for _,phase_steps:=range []int{0,1024}{for _,quantum:=range []float64{1,16}{
  order:=[]string{"M1","M2","C1","C2","M1"};if reverse{order=[]string{"M1","C2","C1","M2","M1"}};v:=native_exposures(order,runs,global,age,amplitude,phase_steps,quantum,0);fits,e:=observe_phase(v,runs,order,128,1000);if e!=nil{t.Fatal(e)};truth:=map[string]float64{"M1":0,"M2":.02,"C1":-.02,"C2":.05};worst:=0.;for _,f:=range fits{err:=math.Abs(math.Remainder(f.Relative-truth[f.Operator],2*math.Pi));worst=math.Max(worst,err)};ret:=math.Abs(fits[4].Relative);maximum=math.Max(maximum,worst);max_return=math.Max(max_return,ret);if worst>.001||ret>.001{t.Fatalf("relative phase guard %g return%g %+v",worst,ret,fits)};rows=append(rows,map[string]interface{}{"reverse":reverse,"globalphase":global,"native_latch_age":age,"amplitude":amplitude,"generic_phase_steps":phase_steps,"quantum":quantum,"maximum_relative_phase_error":worst,"M1return_error":ret})
 }}}}}};evidence:=map[string]interface{}{"records":len(rows),"source":"Independent nativephase integrates4124units/frame then samples every8 with half-native latchage; genericphasequantization,PCMrounding,three tinyinactivecarrier leaks; NOchiprecurrence","fixed_relative_phase_guard_radians":.001,"maximum_relative_phase_error_radians":maximum,"maximum_M1return_phase_error_radians":max_return,"observations":rows};b,e:=json.MarshalIndent(evidence,"","  ");if e!=nil{t.Fatal(e)};dir:=os.Getenv("JT143_PHASE_QUALIFICATION_DIR");if dir==""{dir=t.TempDir()};f,e:=os.OpenFile(filepath.Join(dir,"phase-observer-qualification.json"),os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{t.Fatal(e)};_,e=f.Write(append(b,'\n'));close_error:=f.Close();if e!=nil{t.Fatal(e)};if close_error!=nil{t.Fatal(close_error)};t.Logf("%d independent common-timeline fixtures,maxrelative%g rad,maxreturn%g rad",len(rows),maximum,max_return)
}
func native_exposures(order []string,runs []zero_run,global,age,amplitude float64,phase_steps int,q,jump float64)[]float64{
 phase:=map[string]float64{"M1":0,"M2":.02,"C1":-.02,"C2":.05};v:=make([]float64,16384);native_w:=2*math.Pi*4124/(1<<20);native_phase:=global;native:=make([]float64,16384*8+2);for k:=range native{native[k]=native_phase;native_phase+=native_w};for n:=range v{segment:=0;for _,run:=range runs{if n>=run.End{segment++}};theta:=native[n*8]+age*native_w;value:=-8.;for _,op:=range []string{"M1","M2","C1","C2"}{offset:=phase[op];gain:=.14;if op==order[segment]{gain=amplitude};angle:=theta+offset;if segment==4&&op=="M1"{angle+=jump};if phase_steps>0{unit:=2*math.Pi/float64(phase_steps);angle=unit*math.Floor(angle/unit)};value+=gain*math.Sin(angle)};v[n]=q*math.RoundToEven(value/q)};return v
}
func TestPhaseReturnJumpAndSupport(t *testing.T){
 runs:=[]zero_run{{2000,2064},{4000,4064},{6000,6064},{8000,8064}};order:=[]string{"M1","M2","C1","C2","M1"};v:=native_exposures(order,runs,.37,.5,8170,1024,16,.01);fits,e:=observe_phase(v,runs,order,128,1000);if e!=nil{t.Fatal(e)};if math.Abs(fits[4].Relative-.01)>.001{t.Fatal("return jump concealed",fits[4])};_,e=observe_phase(v,runs,order,128,4000);if e==nil{t.Fatal("short support accepted")};quiet:=make([]float64,16384);_,e=observe_phase(quiet,runs,order,128,1000);if e==nil{t.Fatal("quiet assigned phase")}
}
